  "g2.h.onlybooks": "यी मितिका तपाईंका बिल जुन आपूर्तिकर्ताले अहिलेसम्म रिपोर्ट गरेका छैनन्। GSTR-2B मा नदेखिउन्जेल ITC क्लेम नगर्नुहोस्; आपूर्तिकर्तालाई सम्झाउनुहोस्।",
