  "b3.ac.intro": "बिजनेस र अवधि छान्नुहोस्। फाइल यही डिभाइसमा बन्छ र तपाईं आफैं पठाउनुहुन्छ: WhatsApp, इमेल वा पेन ड्राइभबाट।",
