  "b3.ac.noload": "यो भाग लोड भएन। इन्टरनेट हेरेर फेरि प्रयास गर्नुहोस्।",
  "b3.gd.t": "Google Drive सिंक",
  "b3.gd.p": "आफ्नै Google Drive मार्फत फोन र कम्प्युटरमा डाटा उस्तै राख्नुहोस्। यो एपले त्यहाँ बनाउने एउटा फाइल मात्र हामी हेर्न सक्छौं, र हामीकहाँ केही आउँदैन।",
